"use strict";const utils=require("../utils");module.exports=(defaultFuncs,api,ctx)=>async function changeArchivedStatus(threadIDs,archive,callback){let resolveFunc=()=>{};let rejectFunc=()=>{};const returnPromise=new Promise((resolve,reject)=>{resolveFunc=resolve;rejectFunc=reject});if(utils.getType(archive)==="Function"){callback=archive;archive=true}if(!callback){callback=(err,result)=>{if(err)return rejectFunc(err);resolveFunc(result)}}else{const _userCb=callback;callback=(err,result)=>{if(err){_userCb(err);return rejectFunc(err)}_userCb(null,result);resolveFunc(result)}}try{if(utils.getType(archive)!=="Boolean"){throw new Error("archive parameter must be a boolean")}if(!Array.isArray(threadIDs)){threadIDs=[threadIDs]}const form={should_archive:archive};threadIDs.forEach(id=>{form[`thread_fbids[${id}]`]=true});const res=await defaultFuncs.post("https://www.facebook.com/ajax/mercury/change_archived_status.php",ctx.jar,form).then(utils.parseAndCheckLogin(ctx,defaultFuncs));if(res&&res.error){throw new Error(String(res.error_msg||res.error||"changeArchivedStatus failed"))}callback(null,{success:true})}catch(err){utils.error("changeArchivedStatus",err);callback(err instanceof Error?err:new Error(String(err&&err.message?err.message:err)))}return returnPromise};
